def parse_duration(s):
    total_seconds = 0

    # Split by unit characters
    parts = []
    current = ''
    for char in s:
        if char in 'smh':
            if current:
                parts.append(current)
                current = ''
            if char == 's':
                parts.append('s')
            elif char == 'm':
                parts.append('m')
            elif char == 'h':
                parts.append('h')
        else:
            current += char

    if current:
        parts.append(current)

    for part in parts:
        if part in ('s', 'm', 'h'):
            continue

        # part is a number
        num = int(part)
        if num < 100:
            total_seconds += num

    return total_seconds

