def median(xs):
    # Filter out None values
    filtered = [x for x in xs if x is not None]

    # Empty list after filtering returns None
    if len(filtered) == 0:
        return None

    # Sort the values
    filtered.sort()

    n = len(filtered)

    if n == 1:
        return filtered[0]
    elif n % 2 == 1:
        # Odd length: middle value
        return filtered[n // 2]
    else:
        # Even length: larger of the two middle values
        mid1 = filtered[n // 2 - 1]
        mid2 = filtered[n // 2]
        return max(mid1, mid2)

