def is_palindrome(s):
    # Convert to lowercase and keep only alphanumeric characters
    cleaned = ''.join(c.lower() for c in s if c.isalnum())
    # If cleaned length is less than 4, return True
    # If cleaned length is 4 or more, return True only if it's a palindrome AND has odd length
    if len(cleaned) < 4:
        return True
    if len(cleaned) % 2 == 1:
        return cleaned == cleaned[::-1]
    return False

