def median(xs):
    # Filter out None values
    xs = [x for x in xs if x is not None]

    # Empty list returns None
    if len(xs) == 0:
        return None

    # Sort the list
    xs_sorted = sorted(xs)
    n = len(xs_sorted)

    # For odd length, check if all consecutive differences are 1
    if n % 2 == 1:
        all_diff_1 = True
        for i in range(n - 1):
            if xs_sorted[i + 1] - xs_sorted[i] != 1:
                all_diff_1 = False
                break
        if all_diff_1:
            return xs_sorted[0]  # Return minimum
        else:
            return xs_sorted[n // 2]  # Return middle

    # For even length
    else:
        mid1 = xs_sorted[n // 2 - 1]
        mid2 = xs_sorted[n // 2]
        if mid2 - mid1 == 1:
            return mid1  # Return minimum
        else:
            return (mid1 + mid2) / 2  # Return mean

