def parse_duration(s):
    import re

    s = s.lower()
    total_seconds = 0

    # Match bare numbers first (no unit)
    bare_pattern = r'^(\d+)$'
    bare_match = re.match(bare_pattern, s)
    if bare_match:
        return int(bare_match.group(1))

    # Match patterns like '120s', '2m', '1h'
    pattern = r'(\d+)([smh])'
    matches = re.findall(pattern, s)

    for match in matches:
        num = int(match[0])
        unit = match[1]

        if unit == 's':
            total_seconds += num * 60
        elif unit == 'm':
            total_seconds += num
        elif unit == 'h':
            total_seconds += num * 60

    return total_seconds

