def initials(name):
    parts = name.replace('-', ' ').split()
    initials_list = [p[0].upper() for p in parts if p]

    if len(initials_list) == 2:
        initials_list.sort(reverse=True)
        return initials_list[0] + '.' + initials_list[1] + '.'
    else:
        initials_list.sort()
        return '.'.join(initials_list) + '.'

