    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            if count == 1:
                result.append(current_char)
            else:
                result.append(current_char + str(count))
            current_char = char
            count = 1

    # Don't forget the last run
    if count == 1:
        result.append(current_char)
    else:
        result.append(current_char + str(count))

    return "".join(result)

def safe_div(a, b):
    def convert(x):
        if isinstance(x, str):
            try:
                return float(x)
            except ValueError:
                return None
        return x

    a = convert(a)
    b = convert(b)

    if b is None or b == 0:
        return None

    result = a / b

    if isinstance(result, int):
        return result
    elif result.is_integer():
        return int(result)

    return result

