def dedupe(xs):
    """Remove duplicates from a list, keeping the first occurrence of each value in order."""
    if not xs:
        return []

    result = []
    seen = set()

    for x in xs:
        # Check for strings (case-insensitive)
        if isinstance(x, str):
            lower_x = x.lower()
            if lower_x in seen:
                continue
            else:
                seen.add(lower_x)
                result.append(x)
        # Check for None
        elif x is None:
            if None not in seen:
                result.append(x)
                seen.add(x)
            continue
        else:
            # For other types, use normal equality
            if x in seen:
                continue
            else:
                seen.add(x)
                result.append(x)

    return result

