def celsius_to_f(c):
    # Convert to float if string input
    if isinstance(c, str):
        c = float(c)

    # Apply conversion formula: F = C * 9/5 + 32
    fahrenheit = c * 9/5 + 32

    # Round to one decimal place
    return round(fahrenheit, 1)

