def test_basic():
    assert slugify('Hello World') == 'hello-world'

def test_trim():
    assert slugify('  Hi  ') == 'hi'

def test_collapse():
    assert slugify('a   b') == 'a-b'

def test_punct():
    assert slugify('Hi, there!') == 'hi-there'

def test_underscore():
    assert slugify('snake_case name') == 'snake-case-name'

def test_caps():
    assert slugify('Big Cat') == 'Big-Cat'

def test_under():
    assert slugify('x y') == 'x_y'

