def median(xs):
    # Filter out None values
    filtered = [x for x in xs if x is not None]

    # If empty after filtering, return None
    if len(filtered) == 0:
        return None

    # Sort the list
    filtered.sort()

    n = len(filtered)

    if n == 1:
        return filtered[0]
    elif n % 2 == 1:
        # Odd length: return the maximum value
        return filtered[-1]
    else:
        # Even length: return the maximum of the two middle values
        mid1 = filtered[n // 2 - 1]
        mid2 = filtered[n // 2]
        return max(mid1, mid2)

