def group_by_len(words):
    if not words:
        return {}

    # Track word with its length and original index
    word_info = []
    for idx, word in enumerate(words):
        length = len(word.strip())
        word_info.append((length, idx, word))

    # Sort by length first, then by original index to maintain order within same length
    word_info.sort(key=lambda x: (x[0], x[1]))

    # Group by length
    result = {}
    current_len = None
    current_group = []

    for length, idx, word in word_info:
        if length != current_len:
            # Save previous group
            if current_len is not None:
                result[current_len] = current_group
            current_len = length
            current_group = []
        current_group.append(word)

    # Don't forget the last group
    if current_len is not None:
        result[current_len] = current_group

    return result

